        name, globs = line.split(':',1)
        name=name.strip()
        globs=[g.strip() for g in globs.split(',') if g.strip()]
        TYPE_MAP[name]=globs

def eprint(*a, **kw): print(*a,file=sys.stderr,**kw)
def fail(msg,code=2): eprint(msg); sys.exit(code)

def unescape_sep(s):
    try:
        return bytes(s,"utf-8").decode("unicode_escape")
    except:
        return s

def expand_brace(pat):
    if '{' not in pat:
        return [pat]
    # find first {}
    l=pat.find('{'); r=pat.find('}',l)
    if l==-1 or r==-1 or r<=l+1:
        return [pat]
    pre=pat[:l]; suf=pat[r+1:]; inner=pat[l+1:r]
    # split by comma not inside nested braces? simple
    parts=inner.split(',')
    out=[]
    for pp in parts:
        for ep in expand_brace(pre+pp+suf):
            out.append(ep)
    return out

def glob_match(path, pattern, case_insensitive=False):
    # match pattern against path; mimic globset behavior roughly: pattern may be like *.rs or **/*.rs etc
    # We'll try fnmatch on full path and on basename
    if case_insensitive:
        path=path.lower(); pattern=pattern.lower()
    # expand braces in pattern already? caller expands
    # Use fnmatch.fnmatch for path and basename
    if fnmatch.fnmatch(path, pattern):
        return True
    if fnmatch.fnmatch(os.path.basename(path), pattern):
        return True
    # also try matching against path components with ** etc: use pathlib's match? For **, fnmatch may not handle multi-dir.
    # Simplify: replace ** with * for fnmatch attempt
    # Also handle patterns like "*.rs" should match "a/b.rs" via basename already handled
    # Patterns like "!*.py" handled outside
    return False

